tinymce.PluginManager.add('cifra', function(editor, url) {

    // Add a button that opens a window
    editor.ui.registry.addButton('cifra', {
        text: 'C#',
        tooltip: 'Inserir Nota',
        onAction: function() {

            editor.selection.setContent('<span class="cifra">' + editor.selection.getContent() + '</span>');
        }
    });

    // Adds a menu item to the tools menu
    editor.ui.registry.addMenuItem('cifra', {
        text: 'Inserir Nota',
        context: 'insert',
        onAction: function() {

            editor.selection.setContent('<span class="cifra">' + editor.selection.getContent() + '</span>');
        }
    });

});